            const checked = (t.attrs?.["data-checked"] ?? "") === "true";
            box = checked ? "[x] " : "[ ] ";
          }
          out.push(`${linePrefix()}${marker}${box}`);
          break;
        }

        case "pre":
          blockBreak();
          ctx.inCode = true;
          out.push(`${linePrefix()}\`\`\`\n`);
          break;

        case "code":
          // Inside <pre> the fence already opened; a bare <code> is inline.
          if (!ctx.inCode) {
            ctx.inCode = true;
            emit("`");
          }
          break;

        case "strong":
        case "b":
          emit("**");
          break;
        case "em":
        case "i":
          emit("*");
          break;
        case "s":
        case "del":
        case "strike":
          emit("~~");
          break;
        case "mark":
          // GFM has no highlight delimiter. `==text==` is a non-standard
          // Obsidian/Markdown-it convention and importing it through `marked`
          // produces literal equals signs. Inline HTML is portable GFM and
          // round-trips through the app's existing Markdown importer.
          emit("<mark>");
          break;

        case "a":
          pendingLinkText = [];
          pendingLinkHref = t.attrs?.href ?? "";
          break;

        case "img": {
          const alt = t.attrs?.alt ?? "";
          const src = t.attrs?.src ?? "";
          // A base64 data URI is megabytes of noise in a text file; name it
          // rather than paste it.
          const href = src.startsWith("data:") ? "embedded-image" : src;
          emit(`![${alt}](${href})`);
          break;
        }

        case "table":
          blockBreak();
          table = { rows: [], header: false, caption: "" };
          break;

        case "caption":
          if (table) caption = [];
          break;

        case "figcaption":
          blockBreak();
          out.push("*");
          break;

        case "tr":
          table?.rows.push([]);
          break;

        case "th":
          if (table) table.header = true;
          cell = [];
          break;
        case "td":
          cell = [];
          break;

        case "sup":
        case "sub":
          // No Markdown spelling. GFM allows inline HTML, and keeping the tag
          // is strictly better than silently dropping the character.
          emit(`<${name}>`);
          break;

        case "div":
          if (t.attrs?.["data-page-break"] !== undefined) {
            // A page break has no Markdown meaning; `---` would be a lie,
            // since that is a horizontal rule and the schema already has one.
            break;
          }
          if (!cell && listStack.length === 0) blockBreak();
          break;

        default:
          break;
      }
      continue;
    }

    // close
    switch (name) {
      case "h1":
      case "h2":
      case "h3":
      case "h4":
      case "h5":
      case "h6":
        blockBreak();
        break;

      case "p":
        if (!cell && listStack.length === 0) blockBreak();
        break;

      case "blockquote":
        if (quoteDepth.value > 0) quoteDepth.value--;
        blockBreak();
        break;

      case "ul":
      case "ol":
        listStack.pop();
        if (listStack.length === 0) blockBreak();
        break;

      case "pre":
        ctx.inCode = false;
        out.push(`\n${linePrefix()}\`\`\``);
        blockBreak();
        break;

      case "code":
        if (ctx.inCode && !out.join("").endsWith("```\n")) {
          // Inline code only; the <pre> case is handled above.
          const insidePre = tokens
            .slice(0, i)
            .some((x) => x.kind === "open" && x.name === "pre");
          if (!insidePre) {
            ctx.inCode = false;
            emit("`");
          }
        }
        break;

      case "strong":
      case "b":
        emit("**");
        break;
      case "em":
      case "i":
        emit("*");
        break;
      case "s":
      case "del":
      case "strike":
        emit("~~");
        break;
      case "mark":
        emit("</mark>");
        break;

      case "a": {
        const label = (pendingLinkText ?? []).join("").trim();
        pendingLinkText = null;
        if (!label) break;
        emit(pendingLinkHref ? `[${label}](${pendingLinkHref})` : label);
        pendingLinkHref = "";
        break;
      }

      case "th":
      case "td": {
        const text = (cell ?? []).join("").trim().replace(/\|/g, "\\|");
        cell = null;
        const row = table?.rows[table.rows.length - 1];
        row?.push(text);
        break;
      }

      case "table": {
        if (table && table.rows.length) {
          const rows = table.rows.filter((r) => r.length > 0);
          const width = Math.max(...rows.map((r) => r.length));
          const pad = (r: string[]) =>
            `| ${Array.from({ length: width }, (_, c) => r[c] ?? "").join(" | ")} |`;
          const lines = [pad(rows[0])];
          lines.push(`| ${Array(width).fill("---").join(" | ")} |`);
          for (const r of rows.slice(1)) lines.push(pad(r));
          if (table.caption) {
            out.push(`${linePrefix()}*${table.caption}*\n\n`);
          }
          out.push(linePrefix() + lines.join(`\n${linePrefix()}`));
          blockBreak();
        }
        table = null;
        break;
      }

      case "caption":
        if (table) table.caption = (caption ?? []).join("").trim();
        caption = null;
        break;

      case "figcaption":
        out.push("*");
        blockBreak();
        break;

      case "sup":
      case "sub":
        emit(`</${name}>`);
        break;

      default:
        break;
    }
  }

  return out
    .join("")
    .replace(/[ \t]+$/gm, "")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}
"}

{"chunk_id":"e5af62","wall_time_seconds":0.000006697,"exit_code":0,"original_token_count":1468,"output":"/**
 * Twyne CI pipeline — Dagger TypeScript module.
 *
 * Builds and packages the app in a reproducible container so the exact same
 * flow runs locally (`dagger call all`) and in CI (.github/workflows/ci.yml).
 *
 * Common entrypoints:
 *   dagger call all                  # lint → typecheck → test → build → package
 *   dagger call test                 # just the test suite
 *   dagger call build export --path ./build-output
 *   dagger call package export --path ./release
 *
 * After editing this file run `dagger develop` once to (re)generate the local
 * SDK in `.dagger/sdk` (it is git-ignored).
 */
import {
  dag,
  Container,
  Directory,
  File,
  Secret,
  object,
  func,
  argument,
} from "@dagger.io/dagger";

/** Pinned to match `packageManager` in package.json. */
const BUN_IMAGE = "oven/bun:1.3.6";

/** Paths we never want to upload into the build container. */
const SOURCE_IGNORE = [
  "node_modules",
  ".git",
  ".dagger/sdk",
  "dist",
  "server",
  "release",
  "build-output",
  "desktop/build",
  "tmp",
];

@object()
export class Twyne {
  /**
   * Base container: Bun + the project source with dependencies installed.
   * Uses a cache volume for Bun's global install cache so repeated runs are
   * fast both locally and in CI.
   */
  @func()
  install(
    @argument({ defaultPath: "/", ignore: SOURCE_IGNORE })
    source: Directory,
  ): Container {
    return dag
      .container()
      .from(BUN_IMAGE)
      .withMountedCache(
        "/root/.bun/install/cache",
        dag.cacheVolume("twyne-bun-cache"),
      )
      .withWorkdir("/app")
      .withDirectory("/app", source)
      .withExec(["bun", "install", "--frozen-lockfile"]);
  }

  /** Formatting + ESLint. */
  @func()
  async lint(
    @argument({ defaultPath: "/", ignore: SOURCE_IGNORE })
    source: Directory,
  ): Promise<string> {
    return this.install(source)
      .withExec(["bun", "run", "fmt.check"])
      .withExec(["bun", "run", "lint"])
      .stdout();
  }

  /** TypeScript type checking (tsc --noEmit). */
  @func()
  async typecheck(
    @argument({ defaultPath: "/", ignore: SOURCE_IGNORE })
    source: Directory,
  ): Promise<string> {
    return this.install(source)
      .withExec(["bun", "run", "build.types"])
      .stdout();
  }

  /** The Bun test suite. */
  @func()
  async test(
    @argument({ defaultPath: "/", ignore: SOURCE_IGNORE })
    source: Directory,
  ): Promise<string> {
    return this.install(source).withExec(["bun", "test"]).stdout();
  }

  /**
   * Production build. Returns the built artifacts (`dist/` client bundle and
   * `server/` SSR output) as a Directory you can `export`.
   */
  @func()
  build(
    @argument({ defaultPath: "/", ignore: SOURCE_IGNORE })
    source: Directory,
  ): Directory {
    const built = this.install(source).withExec(["bun", "run", "build"]);
    return dag
      .directory()
      .withDirectory("dist", built.directory("/app/dist"))
      .withDirectory("server", built.directory("/app/server"));
  }

  /**
   * Package a release tarball — mirrors the `release.yml` packaging step.
   * Returns the `.tar.gz` File; `export` it to disk or attach it to a release.
   */
  @func()
  package(
    @argument({ defaultPath: "/", ignore: SOURCE_IGNORE })
    source: Directory,
    version = "dev",
  ): File {
    const tarball = `release/twyne-${version}.tar.gz`;
    return this.install(source)
      .withExec(["bun", "run", "build"])
      .withExec([
        "sh",
        "-c",
        `mkdir -p release && tar --exclude=./node_modules --exclude=./release --exclude=./.git -czf ${tarball} .`,
      ])
      .file(`/app/${tarball}`);
  }

  /**
   * Full CI gate.
   *
   * Lint, typecheck, and unit tests read the same installed source but do not
   * share output directories, so Dagger can evaluate them in parallel.
   * Packaging remains behind all three quality gates: it performs the Qwik
   * client and SSR builds, whose generated manifests/output must stay
   * serialized until those directories are explicitly isolated.
   */
  @func()
  async all(
    @argument({ defaultPath: "/", ignore: SOURCE_IGNORE })
    source: Directory,
  ): Promise<string> {
    await Promise.all([
      this.lint(source),
      this.typecheck(source),
      this.test(source),
    ]);

    // Building the package also covers `build`.
    await this.package(source).sync();
    return "✓ twyne ci: lint, typecheck, test, build, package all passed";
  }

  /**
   * Agent-in-CI seam. Runs an arbitrary command inside the installed project
   * container with an API key wired in as a Dagger secret (never baked into an
   * image layer). This is the hook a coding agent step extends — e.g. running a
   * codegen or review task against the built app.
   */
  @func()
  async agent(
    @argument({ defaultPath: "/", ignore: SOURCE_IGNORE })
    source: Directory,
    /** Shell command for the agent step to run inside /app. */
    command: string,
    /** API key (e.g. ANTHROPIC_API_KEY) exposed to the command as a secret. */
    apiKey?: Secret,
  ): Promise<string> {
    let ctr = this.install(source);
    if (apiKey) {
      ctr = ctr.withSecretVariable("ANTHROPIC_API_KEY", apiKey);
    }
    return ctr.withExec(["sh", "-c", command]).stdout();
  }
}
import { defineConfig } from "vitest/config";

export default defineConfig({
  test: {
    environment: "edge-runtime",
  },
});
